                    delta = base - new_cost
                    if delta > best_delta + 1e-12:
                        best_delta = delta
                        best_i, best_j = i, j
            if best_delta > 1e-12:
                routes[ridx] = r[:best_i] + list(reversed(r[best_i:best_j + 1])) + r[best_j + 1:]
                improved = True

    # Inter-route relocate repair/improvement while preserving feasibility.
    changed = True
    while changed:
        changed = False
        for a in range(len(routes)):
            ra = routes[a]
            la = sum(demand_of(x) for x in ra)
            best = None
            best_gain = 0.0
            for idx, cust in enumerate(list(ra)):
                dc = demand_of(cust)
                for b in range(len(routes)):
                    if a == b:
                        continue
                    rb = routes[b]
                    lb = sum(demand_of(x) for x in rb)
                    if lb + dc > capacity:
                        continue
                    for pos in range(len(rb) + 1):
                        new_ra = ra[:idx] + ra[idx + 1:]
                        new_rb = rb[:pos] + [cust] + rb[pos:]
                        if not new_ra:
                            continue
                        gain = route_cost(ra) + route_cost(rb) - (route_cost(new_ra) + route_cost(new_rb))
                        if gain > best_gain + 1e-12 or (abs(gain - best_gain) <= 1e-12 and best is not None and (cust, b, pos) < best[0]):
                            best_gain = gain
                            best = ((cust, b, pos), new_ra, new_rb)
            if best is not None and best_gain > 1e-12:
                (_, b, _), new_ra, new_rb = best
                routes[a] = new_ra
                routes[b] = new_rb
                changed = True
                break

    # Final clean-up: remove any empties and ensure each customer appears exactly once.
    final_routes = [r for r in routes if r]

    seen = {}
    for ridx, r in enumerate(final_routes):
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    duplicates = [c for c, cnt in seen.items() if cnt > 1]

    # Repair duplicates/missing deterministically by extracting extras into feasible insertions.
    if missing or duplicates:
        # Flatten current routes to reinsert cleanly.
        pool = []
        for r in final_routes:
            pool.extend(r)
        final_routes = []
        loads = []

        for c in pool:
            placed = False
            dc = demand_of(c)
            best_r = -1
            best_pos = -1
            best_inc = None
            for ridx in range(len(final_routes)):
                if loads[ridx] + dc > capacity:
                    continue
                r = final_routes[ridx]
                for pos in range(len(r) + 1):
                    nr = r[:pos] + [c] + r[pos:]
                    inc = route_cost(nr) - route_cost(r)
                    if best_inc is None or inc < best_inc - 1e-12 or (abs(inc - best_inc) <= 1e-12 and (ridx, pos, c) < (best_r, best_pos, c)):
                        best_inc = inc
                        best_r = ridx
                        best_pos = pos
            if best_r >= 0:
                final_routes[best_r] = final_routes[best_r][:best_pos] + [c] + final_routes[best_r][best_pos:]
                loads[best_r] += dc
                placed = True
            if not placed:
                final_routes.append([c])
                loads.append(dc)

        # Ensure all customers present once; if any missing, append them greedily.
        present = {}
        for r in final_routes:
            for c in r:
                present[c] = present.get(c, 0) + 1
        for c in customers:
            if present.get(c, 0) == 0:
                best_r = -1
                best_pos = -1
                best_inc = None
                dc = demand_of(c)
                for ridx in range(len(final_routes)):
                    if loads[ridx] + dc > capacity:
                        continue
                    r = final_routes[ridx]
                    for pos in range(len(r) + 1):
                        nr = r[:pos] + [c] + r[pos:]
                        inc = route_cost(nr) - route_cost(r)
                        if best_inc is None or inc < best_inc - 1e-12:
                            best_inc = inc
                            best_r = ridx
                            best_pos = pos
                if best_r >= 0:
                    final_routes[best_r] = final_routes[best_r][:best_pos] + [c] + final_routes[best_r][best_pos:]
                    loads[best_r] += dc
                else:
                    final_routes.append([c])

    return final_routes
